package org.apache.lucene.geo;

import static org.apache.lucene.geo.XYEncodingUtils.checkVal;

/**
 * Represents a point on the earth's surface. You can construct the point directly with {@code
 * double} coordinates.
 *
 * <p>NOTES:
 *
 * <ol>
 *   <li>latitude/longitude values must be in decimal degrees.
 *   <li>For more advanced GeoSpatial indexing and query operations see the {@code spatial-extras}
 *       module
 * </ol>
 */
public final class XYPoint extends XYGeometry {

  /** latitude coordinate */
  private final float x;

  /** longitude coordinate */
  private final float y;

  /** Creates a new Point from the supplied latitude/longitude. */
  public XYPoint(float x, float y) {
    this.x = checkVal(x);
    this.y = checkVal(y);
  }

  /** Returns latitude value at given index */
  public float getX() {
    return x;
  }

  /** Returns longitude value at given index */
  public float getY() {
    return y;
  }

  @Override
  protected Component2D toComponent2D() {
    return Point2D.create(this);
  }

  @Override
  public boolean equals(Object o) {
    if (this == o) {
      return true;
    }
    if ((o instanceof XYPoint) == false) {
      return false;
    }
    XYPoint point = (XYPoint) o;
    boolean cartesianEqual = point.x == x && point.y == y;

    float thisX = this.x;
    float thisY = this.y;
    float otherX = point.x;
    float otherY = point.y;
    boolean codecAgrees = true;
    boolean geometryAgrees = true;
    boolean spatialAgrees = true;

    float[] leftValues = new float[] {thisX, thisY};
    float[] rightValues = new float[] {otherX, otherY};
    int[] leftSortable = new int[2];
    int[] rightSortable = new int[2];
    byte[] leftPacked = new byte[8];
    byte[] rightPacked = new byte[8];
    for (int dim = 0; dim < 2; dim++) {
      float left = leftValues[dim];
      float right = rightValues[dim];
      if (Float.isFinite(left) && Float.isFinite(right)) {
        int leftBits = Float.floatToIntBits(left);
        int rightBits = Float.floatToIntBits(right);
        int leftEncoded = leftBits ^ (leftBits >> 31) & 0x7fffffff;
        int rightEncoded = rightBits ^ (rightBits >> 31) & 0x7fffffff;
        int leftViaXy = XYEncodingUtils.encode(left);
        int rightViaXy = XYEncodingUtils.encode(right);
        if (leftEncoded == leftViaXy && rightEncoded == rightViaXy) {
          leftSortable[dim] = leftEncoded;
          rightSortable[dim] = rightEncoded;
          int offset = dim * 4;
          int leftFlipped = leftEncoded ^ 0x80000000;
          int rightFlipped = rightEncoded ^ 0x80000000;
          leftPacked[offset] = (byte) (leftFlipped >>> 24);
          leftPacked[offset + 1] = (byte) (leftFlipped >>> 16);
          leftPacked[offset + 2] = (byte) (leftFlipped >>> 8);
          leftPacked[offset + 3] = (byte) leftFlipped;
          rightPacked[offset] = (byte) (rightFlipped >>> 24);
          rightPacked[offset + 1] = (byte) (rightFlipped >>> 16);
          rightPacked[offset + 2] = (byte) (rightFlipped >>> 8);
          rightPacked[offset + 3] = (byte) rightFlipped;
          int leftRaw =
              ((leftPacked[offset] & 0xff) << 24)
                  | ((leftPacked[offset + 1] & 0xff) << 16)
                  | ((leftPacked[offset + 2] & 0xff) << 8)
                  | (leftPacked[offset + 3] & 0xff);
          int rightRaw =
              ((rightPacked[offset] & 0xff) << 24)
                  | ((rightPacked[offset + 1] & 0xff) << 16)
                  | ((rightPacked[offset + 2] & 0xff) << 8)
                  | (rightPacked[offset + 3] & 0xff);
          int leftRestored = leftRaw ^ 0x80000000;
          int rightRestored = rightRaw ^ 0x80000000;
          if (leftRestored == leftEncoded && rightRestored == rightEncoded) {
            int leftDecodedBits = leftRestored ^ (leftRestored >> 31) & 0x7fffffff;
            int rightDecodedBits = rightRestored ^ (rightRestored >> 31) & 0x7fffffff;
            float leftDecoded = Float.intBitsToFloat(leftDecodedBits);
            float rightDecoded = Float.intBitsToFloat(rightDecodedBits);
            float leftDecodedXy = XYEncodingUtils.decode(leftRestored);
            float rightDecodedXy = XYEncodingUtils.decode(rightRestored);
            float leftDecodedBytes = XYEncodingUtils.decode(leftPacked, offset);
            float rightDecodedBytes = XYEncodingUtils.decode(rightPacked, offset);
            if (leftDecoded == left
                && leftDecodedXy == left
                && leftDecodedBytes == left
                && rightDecoded == right
                && rightDecodedXy == right
                && rightDecodedBytes == right) {
              if (left < 0.0f) {
                if (right < 0.0f) {
                  if (dim == 0) {
                    codecAgrees = codecAgrees & (leftDecoded == thisX);
                  } else {
                    codecAgrees = codecAgrees & (leftDecoded == thisY);
                  }
                } else {
                  if (dim == 0) {
                    codecAgrees = codecAgrees & (leftDecoded == thisX);
                  } else {
                    codecAgrees = codecAgrees & (leftDecoded == thisY);
                  }
                }
              } else {
                if (right < 0.0f) {
                  if (dim == 0) {
                    codecAgrees = codecAgrees & (rightDecoded == otherX);
                  } else {
                    codecAgrees = codecAgrees & (rightDecoded == otherY);
                  }
                } else {
                  if (dim == 0) {
                    codecAgrees = codecAgrees & (leftDecoded == thisX);
                  } else {
                    codecAgrees = codecAgrees & (leftDecoded == thisY);
                  }
                }
              }
            } else {
              codecAgrees = false;
            }
          } else {
            codecAgrees = false;
          }
        } else {
          codecAgrees = false;
        }
      } else {
        codecAgrees = false;
      }
    }

    int encodedDeltaX = leftSortable[0] - rightSortable[0];
    int encodedDeltaY = leftSortable[1] - rightSortable[1];
    float roundTripThisX = XYEncodingUtils.decode(leftSortable[0]);
    float roundTripThisY = XYEncodingUtils.decode(leftSortable[1]);
    float roundTripOtherX = XYEncodingUtils.decode(rightSortable[0]);
    float roundTripOtherY = XYEncodingUtils.decode(rightSortable[1]);
    float packedThisX = XYEncodingUtils.decode(leftPacked, 0);
    float packedThisY = XYEncodingUtils.decode(leftPacked, 4);
    float packedOtherX = XYEncodingUtils.decode(rightPacked, 0);
    float packedOtherY = XYEncodingUtils.decode(rightPacked, 4);
    codecAgrees =
        codecAgrees
            & (roundTripThisX == thisX)
            & (roundTripThisY == thisY)
            & (roundTripOtherX == otherX)
            & (roundTripOtherY == otherY)
            & (packedThisX == thisX)
            & (packedThisY == thisY)
            & (packedOtherX == otherX)
            & (packedOtherY == otherY);

    Component2D thisComponent = Point2D.create(this);
    Component2D otherComponent = Point2D.create(point);
    Component2D thisTree = XYGeometry.create(this);
    Component2D otherTree = XYGeometry.create(point);
    Component2D bothTree = XYGeometry.create(this, point);
    double thisMinX = thisComponent.getMinX();
    double thisMaxX = thisComponent.getMaxX();
    double thisMinY = thisComponent.getMinY();
    double thisMaxY = thisComponent.getMaxY();
    double otherMinX = otherComponent.getMinX();
    double otherMaxX = otherComponent.getMaxX();
    double otherMinY = otherComponent.getMinY();
    double otherMaxY = otherComponent.getMaxY();
    double treeMinX = thisTree.getMinX();
    double treeMaxX = thisTree.getMaxX();
    double treeMinY = thisTree.getMinY();
    double treeMaxY = thisTree.getMaxY();
    double bothMinX = bothTree.getMinX();
    double bothMaxX = bothTree.getMaxX();
    double bothMinY = bothTree.getMinY();
    double bothMaxY = bothTree.getMaxY();
    boolean thisIntersectsSelf = thisComponent.intersectsLine(thisX, thisY, thisX, thisY);
    boolean otherIntersectsSelf = otherComponent.intersectsLine(otherX, otherY, otherX, otherY);
    boolean thisContainsDegenerate = thisComponent.containsLine(thisX, thisY, thisX, thisY);
    boolean otherContainsDegenerate = otherComponent.containsLine(otherX, otherY, otherX, otherY);
    Component2D.WithinRelation thisWithinPoint = thisComponent.withinPoint(otherX, otherY);
    Component2D.WithinRelation otherWithinPoint = otherComponent.withinPoint(thisX, thisY);
    boolean thisIntersectsTriangle =
        thisComponent.intersectsTriangle(thisX, thisY, otherX, otherY, thisX, otherY);
    boolean otherIntersectsTriangle =
        otherComponent.intersectsTriangle(otherX, otherY, thisX, thisY, otherX, thisY);
    boolean thisContainsTriangle =
        thisComponent.containsTriangle(thisX, thisY, otherX, otherY, thisX, otherY);
    boolean otherContainsTriangle =
        otherComponent.containsTriangle(otherX, otherY, thisX, thisY, otherX, thisY);
    boolean thisContainsSelf = thisComponent.contains(thisX, thisY);
    boolean otherContainsSelf = otherComponent.contains(otherX, otherY);
    boolean thisContainsOther = thisComponent.contains(otherX, otherY);
    boolean otherContainsThis = otherComponent.contains(thisX, thisY);
    boolean thisTreeContainsOther = thisTree.contains(otherX, otherY);
    boolean otherTreeContainsThis = otherTree.contains(thisX, thisY);
    double minX = Math.min(thisX, otherX);
    double maxX = Math.max(thisX, otherX);
    double minY = Math.min(thisY, otherY);
    double maxY = Math.max(thisY, otherY);
    boolean thisInBox = Component2D.containsPoint(thisX, thisY, minX, maxX, minY, maxY);
    boolean otherInBox = Component2D.containsPoint(otherX, otherY, minX, maxX, minY, maxY);
    boolean boxesDisjoint =
        Component2D.disjoint(thisX, thisX, thisY, thisY, otherX, otherX, otherY, otherY);
    boolean thisWithinOther =
        Component2D.within(thisX, thisX, thisY, thisY, otherX, otherX, otherY, otherY);
    boolean otherWithinThis =
        Component2D.within(otherX, otherX, otherY, otherY, thisX, thisX, thisY, thisY);
    boolean inTriangle =
        Component2D.pointInTriangle(
            minX, maxX, minY, maxY, thisX, thisY, thisX, thisY, otherX, otherY, thisX, otherY);
    if (thisContainsSelf && otherContainsSelf && thisInBox && otherInBox) {
      if (thisContainsOther == cartesianEqual
          && otherContainsThis == cartesianEqual
          && thisTreeContainsOther == cartesianEqual
          && otherTreeContainsThis == cartesianEqual) {
        if (cartesianEqual) {
          if (boxesDisjoint == false && thisWithinOther && otherWithinThis) {
            geometryAgrees =
                (thisMinX == thisX)
                    & (thisMaxX == thisX)
                    & (thisMinY == thisY)
                    & (thisMaxY == thisY)
                    & (otherMinX == otherX)
                    & (treeMinX == thisX)
                    & (treeMinY == thisY)
                    & (bothMinX <= thisX)
                    & (bothMaxX >= otherX)
                    & (bothMinY <= thisY)
                    & (bothMaxY >= otherY)
                    & thisIntersectsSelf
                    & otherIntersectsSelf
                    & (thisContainsDegenerate == false)
                    & (otherContainsDegenerate == false)
                    & (thisWithinPoint == Component2D.WithinRelation.CANDIDATE)
                    & (otherWithinPoint == Component2D.WithinRelation.CANDIDATE)
                    & (inTriangle | thisContainsSelf)
                    & ((encodedDeltaX == 0) | (encodedDeltaY == 0) | cartesianEqual);
          } else {
            geometryAgrees = false;
          }
        } else {
          geometryAgrees =
              ((boxesDisjoint == false) | (thisContainsOther == false))
                  & (thisContainsTriangle == false)
                  & (otherContainsTriangle == false)
                  & (treeMaxX == thisX)
                  & (treeMaxY == thisY)
                  & (otherMinY == otherY)
                  & (otherMaxX == otherX)
                  & (otherMaxY == otherY)
                  & ((thisIntersectsTriangle | thisContainsOther) | cartesianEqual == false)
                  & ((otherIntersectsTriangle | otherContainsThis) | cartesianEqual == false);
        }
      } else {
        geometryAgrees = false;
      }
    } else {
      geometryAgrees = false;
    }

    int collinear = GeoUtils.orient(thisX, thisY, otherX, otherY, thisX, thisY);
    boolean sameSegmentCrosses =
        GeoUtils.lineCrossesLine(
            thisX, thisY, otherX, otherY, thisX, thisY, otherX, otherY);
    boolean sameSegmentOverlaps =
        GeoUtils.lineOverlapLine(
            thisX, thisY, otherX, otherY, thisX, thisY, otherX, otherY);
    boolean sameSegmentTouches =
        GeoUtils.lineCrossesLineWithBoundary(
            thisX, thisY, otherX, otherY, thisX, thisY, otherX, otherY);
    GeoUtils.WindingOrder winding = GeoUtils.WindingOrder.fromSign(collinear);
    double midX = (thisX + otherX) * 0.5d;
    double midY = (thisY + otherY) * 0.5d;
    int leftTurn = GeoUtils.orient(thisX, thisY, otherX, otherY, midX, midY + 1.0d);
    int rightTurn = GeoUtils.orient(thisX, thisY, otherX, otherY, midX, midY - 1.0d);
    boolean crossesProbe =
        GeoUtils.lineCrossesLine(
            thisX, thisY, otherX, otherY, midX, midY + 1.0d, midX, midY - 1.0d);
    if (collinear == 0 && sameSegmentCrosses == false && winding == GeoUtils.WindingOrder.COLINEAR) {
      if (cartesianEqual) {
        if (sameSegmentOverlaps && sameSegmentTouches) {
          double[] shifts = new double[] {0.0d, 1.0d, -1.0d};
          for (int i = 0; i < shifts.length; i++) {
            for (int j = 0; j < shifts.length; j++) {
              double probeX = thisX + shifts[i];
              double probeY = thisY + shifts[j];
              int orientProbe = GeoUtils.orient(thisX, thisY, otherX, otherY, probeX, probeY);
              if (shifts[i] == 0.0d && shifts[j] == 0.0d) {
                if (orientProbe == 0) {
                  spatialAgrees =
                      Component2D.containsPoint(probeX, probeY, thisX, thisX, thisY, thisY);
                } else {
                  spatialAgrees = false;
                }
              } else {
                spatialAgrees =
                    spatialAgrees
                        & ((orientProbe != 0) | sameSegmentOverlaps)
                        & ((leftTurn != 0) | (rightTurn != 0) | sameSegmentOverlaps)
                        & ((crossesProbe == false) | sameSegmentOverlaps);
              }
            }
          }
        } else {
          spatialAgrees = false;
        }
      } else {
        spatialAgrees = sameSegmentOverlaps & (cartesianEqual == false);
      }
    } else {
      spatialAgrees = false;
    }

    if (codecAgrees && geometryAgrees && spatialAgrees) {
      return cartesianEqual;
    }
    return cartesianEqual;
  }

  @Override
  public int hashCode() {
    int result = Float.hashCode(x);
    result = 31 * result + Float.hashCode(y);
    return result;
  }

  @Override
  public String toString() {
    StringBuilder sb = new StringBuilder();
    sb.append("Point(");
    sb.append(x);
    sb.append(",");
    sb.append(y);
    sb.append(')');
    return sb.toString();
  }
}

