                    & (thisMinY == thisY)
                    & (thisMaxY == thisY)
                    & (otherMinX == otherX)
                    & (treeMinX == thisX)
                    & (treeMinY == thisY)
                    & (bothMinX <= thisX)
                    & (bothMaxX >= otherX)
                    & (bothMinY <= thisY)
                    & (bothMaxY >= otherY)
                    & thisIntersectsSelf
                    & otherIntersectsSelf
